#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line);
    istringstream iss(line);
    int baseW, numberM;
    iss >> baseW >> numberM;

    int r = numberM;
    int e = (int)(log(r) / log(baseW));
    int len = e + 2;
    vector<int> digitsArr(len, 0);

    for (int power = e; power >= 0; --power) {
        digitsArr[power] = (int)((r / pow(baseW, power)) % baseW);
    }

    bool validSequence = true;
    for (int i = 0; i <= e; ++i) {
        if (digitsArr[i] >= baseW) {
            digitsArr[i] %= baseW;
            if (i + 1 < len) {
                digitsArr[i + 1]++;
            }
        }
        if (digitsArr[i] != 0 && digitsArr[i] != 1) {
            digitsArr[i]++;
        }
        if (digitsArr[i] >= baseW) {
            digitsArr[i] %= baseW;
            if (i + 1 < len) {
                digitsArr[i + 1]++;
            }
        }
    }

    for (int i = 0; i < len; ++i) {
        if (digitsArr[i] != 0 && digitsArr[i] != 1) {
            validSequence = false;
            break;
        }
    }

    cout << (validSequence ? "YES" : "NO") << "\n";

    return 0;
}
